function risky(callback) {
  setTimeout(() => {
    try {
      callback();
    } catch (error) {
      console.log("risky caught: " + error.message);
    }
  }, 0);
}

try {
  risky(() => {
    throw new Error("boom");
  });
  console.log("outer done");
} catch {
  console.log("outer caught");
}

console.log("end");
